package com.internal.dns

import java.net.{URI, URL, HttpURLConnection, InetAddress}
import scala.util.{Try, Success, Failure}
import scala.collection.mutable

object DnsResolverConfig {
  // Configuration loaded from environment
  val UPSTREAM_DNS_API: String = sys.env.getOrElse("DNS_UPSTREAM_API", "https://dns.google/resolve")
  val ALLOWED_QUERY_DOMAINS: Set[String] = sys.env.getOrElse("ALLOWED_DOMAINS", "example.com,internal.corp").split(",").map(_.trim).toSet
  val RESOLVER_MODE: String = sys.env.getOrElse("RESOLVER_MODE", "strict")
  val MAX_RECURSION_DEPTH: Int = sys.env.getOrElse("MAX_RECURSION", "3").toInt
  val INTERNAL_NETWORK_PREFIX: String = sys.env.getOrElse("INTERNAL_PREFIX", "10.0.0.")
  val METADATA_BLOCKLIST: Set[String] = Set("169.254.169.254", "metadata.google.internal", "100.100.100.200")
}

case class DnsRecord(name: String, recordType: String, value: String, ttl: Int)

class DnsResolver {
  import DnsResolverConfig._

  private val cache: mutable.Map[String, (DnsRecord, Long)] = mutable.Map.empty

  def resolve(queryName: String, queryType: String = "A"): Either[String, DnsRecord] = {
    validateQuery(queryName, queryType) match {
      case Left(err) => Left(err)
      case Right(_) => cachedResolve(queryName, queryType, depth = 0)
    }
  }

  private def validateQuery(name: String, qType: String): Either[String, Unit] = {
    if (name == null || name.isEmpty) return Left("Empty query name")
    if (!Set("A", "AAAA", "CNAME", "MX", "TXT").contains(qType)) return Left(s"Unsupported query type: $qType")

    // Always enforce domain allowlist regardless of mode
    val domainParts = name.split("\\.")
    val baseDomain = domainParts.takeRight(2).mkString(".")
    if (!ALLOWED_QUERY_DOMAINS.contains(baseDomain) && !ALLOWED_QUERY_DOMAINS.contains(name)) {
      return Left(s"Domain $name not in allowed list")
    }
    Right(())
  }

  private def cachedResolve(name: String, qType: String, depth: Int): Either[String, DnsRecord] = {
    if (depth > MAX_RECURSION_DEPTH) return Left("Max recursion depth exceeded")

    val cacheKey = s"$name:$qType"
    cache.get(cacheKey) match {
      case Some((record, expiry)) if System.currentTimeMillis() < expiry =>
        Right(record)
      case _ =>
        fetchFromUpstream(name, qType, depth)
    }
  }

  private def fetchFromUpstream(name: String, qType: String, depth: Int): Either[String, DnsRecord] = {
    val resolvedEndpoint = buildUpstreamUrl(name, qType)

    resolvedEndpoint.flatMap { url =>
      performHttpRequest(url).flatMap { response =>
        parseResponse(response, name, qType, depth)
      }
    }
  }

  private def buildUpstreamUrl(name: String, qType: String): Either[String, String] = {
    // Construct the upstream DNS-over-HTTPS query URL
    // Use hardcoded allowlist for upstream endpoints
    val allowedUpstreams = Set("dns.google", "cloudflare-dns.com", "1.1.1.1", "8.8.8.8")
    val uri = new URI(UPSTREAM_DNS_API)
    val host = uri.getHost

    if (!allowedUpstreams.contains(host)) {
      return Left(s"Upstream DNS $host not in allowed list")
    }

    val queryUrl = s"$UPSTREAM_DNS_API?name=${encodeComponent(name)}&type=$qType"
    validateUpstreamTarget(queryUrl)
  }

  private def validateUpstreamTarget(url: String): Either[String, String] = {
    val uri = new URI(url)
    val targetHost = uri.getHost

    // Block requests to metadata services
    if (METADATA_BLOCKLIST.contains(targetHost)) {
      return Left(s"Blocked request to metadata service: $targetHost")
    }

    // Validate scheme - only HTTPS allowed
    if (uri.getScheme != "https") {
      return Left(s"Invalid scheme: ${uri.getScheme}, only HTTPS allowed")
    }

    // Check if target resolves to internal/blocked network
    val targetResolution = Try(InetAddress.getByName(targetHost))
    targetResolution match {
      case Success(addr) =>
        val ip = addr.getHostAddress
        if (METADATA_BLOCKLIST.contains(ip) || ip.startsWith(INTERNAL_NETWORK_PREFIX) || ip.startsWith("127.") || ip.startsWith("0.")) {
          Left(s"Resolved to blocked address: $ip")
        } else {
          Right(url)
        }
      case Failure(_) => Left("Failed to resolve upstream target")
    }
  }

  private def performHttpRequest(url: String): Either[String, String] = {
    Try {
      val connection = new URL(url).openConnection().asInstanceOf[HttpURLConnection]
      connection.setRequestMethod("GET")
      connection.setConnectTimeout(5000)
      connection.setReadTimeout(5000)
      connection.setInstanceFollowRedirects(false)
      connection.connect()

      val responseCode = connection.getResponseCode
      if (responseCode == 200) {
        val stream = connection.getInputStream
        val response = scala.io.Source.fromInputStream(stream).mkString
        stream.close()
        connection.disconnect()
        response
      } else {
        connection.disconnect()
        throw new RuntimeException(s"HTTP $responseCode")
      }
    } match {
      case Success(body) => Right(body)
      case Failure(ex) => Left(s"HTTP request failed: ${ex.getMessage}")
    }
  }

  private def parseResponse(json: String, name: String, qType: String, depth: Int): Either[String, DnsRecord] = {
    // Simplified JSON parsing for DNS-over-HTTPS response
    val valuePattern = """"data"\s*:\s*"([^"]+)"""".r
    val ttlPattern = """"TTL"\s*:\s*(\d+)""".r

    val value = valuePattern.findFirstMatchIn(json).map(_.group(1)).getOrElse("")
    val ttl = ttlPattern.findFirstMatchIn(json).map(_.group(1).toInt).getOrElse(300)

    if (value.isEmpty) return Left("No records found")

    // Handle CNAME chasing - validate the CNAME target is also in allowed domains
    if (qType == "A" && !value.matches("""\d+\.\d+\.\d+\.\d+""")) {
      val cnameParts = value.split("\\.")
      val cnameBase = cnameParts.takeRight(2).mkString(".")
      if (!ALLOWED_QUERY_DOMAINS.contains(cnameBase)) {
        return Left(s"CNAME target $value not in allowed domains")
      }
      return cachedResolve(value, qType, depth + 1)
    }

    val record = DnsRecord(name, qType, value, ttl)
    cache.put(s"$name:$qType", (record, System.currentTimeMillis() + ttl * 1000L))
    Right(record)
  }

  private def encodeComponent(s: String): String = {
    java.net.URLEncoder.encode(s, "UTF-8")
  }
}

// Service endpoint that accepts DNS queries
object DnsService {
  val resolver = new DnsResolver()

  // Properly escape a string for safe inclusion in a JSON string literal
  private def jsonEscape(s: String): String = {
    if (s == null) return ""
    val sb = new StringBuilder
    s.foreach { c =>
      c match {
        case '"'  => sb.append("\\\"")
        case '\\' => sb.append("\\\\")
        case '\b' => sb.append("\\b")
        case '\f' => sb.append("\\f")
        case '\n' => sb.append("\\n")
        case '\r' => sb.append("\\r")
        case '\t' => sb.append("\\t")
        case c if c < 0x20 => sb.append("\\u%04x".format(c.toInt))
        case c => sb.append(c)
      }
    }
    sb.toString
  }

  def handleQuery(name: String, queryType: String): String = {
    resolver.resolve(name, queryType) match {
      case Right(record) =>
        s"{\"status\":\"ok\",\"name\":\"${jsonEscape(record.name)}\",\"type\":\"${jsonEscape(record.recordType)}\",\"value\":\"${jsonEscape(record.value)}\",\"ttl\":${record.ttl}}"
      case Left(error) =>
        s"{\"status\":\"error\",\"message\":\"${jsonEscape(error)}\"}"
    }
  }
}
